use clap::{crate_name, crate_version, App as ClapApp, AppSettings, Arg, ArgGroup, SubCommand};
use once_cell::sync::Lazy;
use std::env;
use std::path::Path;

use crate::config::PagingSpec;

static VERSION: Lazy<String> = Lazy::new(|| {
    #[cfg(feature = "bugreport")]
    let git_version = bugreport::git_version!(fallback = "");
    #[cfg(not(feature = "bugreport"))]
    let git_version = "";

    if git_version.is_empty() {
        crate_version!().to_string()
    } else {
        format!("{} ({})", crate_version!(), git_version)
    }
});

struct CliApp {
    interactive_output: bool,
    no_color: bool,
}

impl CliApp {
    fn new(interactive_output: bool) -> Self {
        Self {
            interactive_output,
            no_color: env::var_os("NO_COLOR").is_some(),
        }
    }

    fn with_paging_args(&self, app: ClapApp<'static, 'static>) -> ClapApp<'static, 'static> {
        let spec = PagingSpec::standard();
        let clap_color_setting = if self.interactive_output && !self.no_color {
            AppSettings::ColoredHelp
        } else {
            AppSettings::ColorNever
        };

        app.global_setting(clap_color_setting)
            .arg(
                Arg::with_name(spec.paging_long)
                    .long(spec.paging_long)
                    .overrides_with(spec.paging_long)
                    .takes_value(true)
                    .value_name(spec.value_name)
                    .possible_values(spec.possible_values)
                    .default_value(spec.default_value)
                    .hide_default_value(true)
                    .help("Specify when to use the pager, or use `-P` to disable (*auto*, never, always).")
                    .long_help(
                        "Specify when to use the pager. To disable the pager, use \
                        --paging=never' or its alias,'-P'. To disable the pager permanently, \
                        set BAT_PAGER to an empty string. To control which pager is used, see the \
                        '--pager' option. Possible values: *auto*, never, always."
                    ),
            )
            .arg(
                Arg::with_name(spec.no_paging_long)
                    .short(spec.no_paging_short)
                    .long(spec.no_paging_long)
                    .alias("no-pager")
                    .overrides_with(spec.no_paging_long)
                    .hidden(true)
                    .hidden_short_help(true)
                    .help("Alias for '--paging=never'")
            )
            .arg(
                Arg::with_name(spec.pager_flag)
                    .long(spec.pager_flag)
                    .overrides_with(spec.pager_flag)
                    .takes_value(true)
                    .value_name("command")
                    .hidden_short_help(true)
                    .help("Determine which pager to use.")
                    .long_help(
                        "Determine which pager is used. This option will override the \
                        PAGER and BAT_PAGER environment variables. The default pager is 'less'. \
                        To control when the pager is used, see the '--paging' option. \
                        Example: '--pager \"less -RF\"'."
                    ),
            )
    }
}

pub fn build_app(interactive_output: bool) -> ClapApp<'static, 'static> {
    let cli = CliApp::new(interactive_output);

    let mut app = ClapApp::new(crate_name!())
        .version(VERSION.as_str())
        .global_setting(AppSettings::DeriveDisplayOrder)
        .global_setting(AppSettings::UnifiedHelpMessage)
        .global_setting(AppSettings::HidePossibleValuesInHelp)
        .setting(AppSettings::ArgsNegateSubcommands)
        .setting(AppSettings::AllowExternalSubcommands)
        .setting(AppSettings::DisableHelpSubcommand)
        .setting(AppSettings::VersionlessSubcommands)
        .max_term_width(100)
        .about(
            "A cat(1) clone with wings.\n\n\
             Use '--help' instead of '-h' to see a more detailed version of the help text.",
        )
        .after_help(
            "Note: `bat -h` prints a short and concise overview while `bat --help` gives all \
